from collections import defaultdict
import random
T=('held','aligned')
def act(p,q):
 q=dict(q)
 if p=='grasp': q['held']=True
 if p=='align' and q['held']: q['aligned']=True
 return q
def common(s,H=4):
 q={'held':False,'aligned':False}; i=0
 for _ in range(H):
  if i>=len(s): return 'UNDEFINED_NO_PHASE_TEXT'
  q=act(s[i],q)
  if i<len(T) and q[T[i]]: i+=1
  if q['held'] and q['aligned']: return 'SUCCESS'
 return 'TIMEOUT'
def specific(s):
 q={'held':False,'aligned':False}
 for p in s: q=act(p,q)
 return 'SUCCESS' if q['held'] and q['aligned'] else 'FAIL'
def rate(v): return sum(v)/len(v)
def score(cal,ev,order):
 xs=sorted(cal); star={x:min(order,key=lambda s:(rate(cal[x][s]),order.index(s))) for x in xs}; fix=min(order,key=lambda s:(sum(rate(cal[x][s]) for x in xs),order.index(s))); terms=[rate(ev[x][fix])-rate(ev[x][star[x]]) for x in xs]; return star,fix,sum(terms)/len(terms)
for n,s in {'ref':('grasp','align'),'rev':('align','grasp'),'short':('grasp',),'extra':('grasp','align','verify')}.items(): print('schedule',n,'common=',common(s),'schedule_specific=',specific(s))
cal={'A':{'s0':[0]*20,'s1':[1]*20},'B':{'s0':[1]*20,'s1':[0]*20}}; ev=cal
star,fix,G=score(cal,ev,['s0','s1']); print('reversal','star=',star,'fix=',fix,'G_E=',G)
flat={x:{s:[0,1]*10 for s in ('s0','s1')} for x in ('A','B')}; print('flat-null','star/fix/G_E=',score(flat,flat,['s0','s1']))
single={x:{'s0':[0,1]*10} for x in ('A','B')}; print('singleton','star/fix/G_E=',score(single,single,['s0']))
try: cal['C']
except KeyError: print('heldout-C','s_star(C)=UNDEFINED without C-specific calibration')
def perm(star,tr):
 g=defaultdict(list)
 for x,t in tr.items(): g[t].append(x)
 out=dict(star)
 for xs in g.values():
  vals=[star[x] for x in xs]
  for x,v in zip(xs,vals[1:]+vals[:1]): out[x]=v
 return out
print('permute-unique',perm(star,{'A':'T_A','B':'T_B'})); print('permute-shared',perm(star,{'A':'T','B':'T'})); print('physical-reset','same fiducial hash; hidden histories [0,1]; outcomes [1,0]')
rng=random.Random(2305); gs=[]
for _ in range(10000):
 c={}; e={}
 for x in range(6):
  c[x]={}; e[x]={}
  for s in ('s0','s1'): c[x][s]=[rng.random()<.5 for _ in range(20)]; e[x][s]=[rng.random()<.5 for _ in range(20)]
 gs.append(score(c,e,['s0','s1'])[2])
print('null-MC-instance-contingent','mean_G_E=',round(sum(gs)/len(gs),6))
